DROP TABLE IF EXISTS `password_reset_tokens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `password_reset_tokens` (
  `PasswordResetID` bigint NOT NULL AUTO_INCREMENT,
  `UserID` int DEFAULT NULL,
  `CustomerID` int DEFAULT NULL,
  `TokenHash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'HMAC-SHA-256 hash of the OTP; never store the raw token',
  `ExpiresAt` datetime NOT NULL,
  `UsedAt` datetime DEFAULT NULL,
  `FailedAttempts` tinyint unsigned NOT NULL DEFAULT '0',
  `CreatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`PasswordResetID`),
  UNIQUE KEY `TokenHash` (`TokenHash`),
  KEY `idx_password_reset_expiry` (`ExpiresAt`,`UsedAt`),
  KEY `fk_password_reset_user` (`UserID`),
  KEY `fk_password_reset_customer` (`CustomerID`),
  CONSTRAINT `fk_password_reset_customer` FOREIGN KEY (`CustomerID`) REFERENCES `customers` (`CustomerID`) ON DELETE CASCADE,
  CONSTRAINT `fk_password_reset_user` FOREIGN KEY (`UserID`) REFERENCES `users` (`UserID`) ON DELETE CASCADE,
  CONSTRAINT `chk_password_reset_account` CHECK ((((`UserID` is not null) and (`CustomerID` is null)) or ((`UserID` is null) and (`CustomerID` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
