DROP TABLE IF EXISTS `product_serials`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_serials` (
  `SerialID` int NOT NULL AUTO_INCREMENT,
  `ProductID` int NOT NULL,
  `SerialNumber` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'AVAILABLE' COMMENT 'AVAILABLE, SOLD, WARRANTY, DEFECTIVE',
  `InboundDetailID` int DEFAULT NULL COMMENT 'Nhập từ phiếu nào',
  `OrderDetailID` int DEFAULT NULL COMMENT 'Xuất ở đơn hàng nào',
  PRIMARY KEY (`SerialID`),
  UNIQUE KEY `SerialNumber` (`SerialNumber`),
  KEY `fk_serials_product` (`ProductID`),
  KEY `fk_serials_inbound` (`InboundDetailID`),
  KEY `fk_serials_orderdetail` (`OrderDetailID`),
  CONSTRAINT `fk_serials_inbound` FOREIGN KEY (`InboundDetailID`) REFERENCES `inbound_details` (`InboundDetailID`) ON DELETE SET NULL,
  CONSTRAINT `fk_serials_orderdetail` FOREIGN KEY (`OrderDetailID`) REFERENCES `order_details` (`OrderDetailID`) ON DELETE SET NULL,
  CONSTRAINT `fk_serials_product` FOREIGN KEY (`ProductID`) REFERENCES `products` (`ProductID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
