--
-- Table structure for table `promotions`
--

DROP TABLE IF EXISTS `promotions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `promotions` (
  `PromotionID` int NOT NULL AUTO_INCREMENT,
  `Code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `DiscountType` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PERCENT, FIXED_AMOUNT',
  `DiscountValue` decimal(15,2) NOT NULL,
  `MinOrderAmount` decimal(15,2) DEFAULT '0.00',
  `MaxDiscountAmount` decimal(15,2) DEFAULT NULL,
  `UsageLimit` int DEFAULT '0' COMMENT '0 = Không giới hạn',
  `UsedCount` int DEFAULT '0',
  `StartDate` datetime NOT NULL,
  `EndDate` datetime NOT NULL,
  `IsActive` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`PromotionID`),
  UNIQUE KEY `Code` (`Code`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

