DROP TABLE IF EXISTS `warranties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `warranties` (
  `WarrantyID` int NOT NULL AUTO_INCREMENT,
  `OrderDetailID` int NOT NULL,
  `SerialNumber` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `StartDate` date NOT NULL,
  `EndDate` date NOT NULL,
  `Status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT 'ACTIVE, EXPIRED, CLAIMED',
  PRIMARY KEY (`WarrantyID`),
  KEY `fk_warranties_odetail` (`OrderDetailID`),
  CONSTRAINT `fk_warranties_odetail` FOREIGN KEY (`OrderDetailID`) REFERENCES `order_details` (`OrderDetailID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

